package com.flightparty.table;

import jakarta.servlet.http.HttpServletRequest;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

@Service
public class TableService {
 public record Seat(UUID principal,UUID account,String name,boolean bot) {}
 public record Room(UUID id,String game,String origin,String phase,List<Seat> seats,GridRules.State board,long version,long deadline,Map<String,Long> guesses) {public Room(UUID id,String game,String origin,String phase,List<Seat> seats,GridRules.State board,long version,long deadline){this(id,game,origin,phase,seats,board,version,deadline,Map.of());}}
 public record PublicSeat(String name,boolean bot,boolean member,boolean annualMember,String avatarUrl,String frame) {}
 public record View(UUID id,String game,String origin,String phase,List<String> names,List<Boolean> bots,List<PublicSeat> profiles,GridRules.State board,long version,long deadline,long serverNow,int you) {}
 private final JdbcClient db;private final ObjectMapper json;private final com.flightparty.auth.AppearanceService appearances;
 public TableService(JdbcClient db,ObjectMapper json,com.flightparty.auth.AppearanceService appearances){this.db=db;this.json=json;this.appearances=appearances;}
 private UUID principal(HttpServletRequest r){var s=r.getSession(false);var p=s==null?null:s.getAttribute("flightparty.principal");if(p==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return UUID.fromString(p.toString());}
 private Seat seat(UUID p){var account=db.sql("select account_id from principals where id=:id").param("id",p).query(UUID.class).optional().orElse(null);var name=account==null?"游客":db.sql("select display_name from accounts where id=:id").param("id",account).query(String.class).single();return new Seat(p,account,name,false);}
 private Room read(UUID id){return db.sql("select state from table_rooms where id=:id for update").param("id",id).query(String.class).optional().map(s->json.readValue(s,Room.class)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 private void write(Room r){db.sql("update table_rooms set state=:s,phase=:phase,updated_at=now() where id=:id").param("s",json.writeValueAsString(r)).param("phase",r.phase).param("id",r.id).update();}
 private int member(Room r,UUID p){for(int i=0;i<r.seats.size();i++)if(p.equals(r.seats.get(i).principal))return i;throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 private Room changed(Room r,String phase,List<Seat> seats,GridRules.State board,long deadline){return new Room(r.id,r.game,r.origin,phase,List.copyOf(seats),board,r.version+1,deadline,r.guesses);}
 private View view(Room r,UUID p){return new View(r.id,r.game,r.origin,r.phase,r.seats.stream().map(Seat::name).toList(),r.seats.stream().map(Seat::bot).toList(),r.seats.stream().map(s->{var a=s.account==null?null:appearances.get(s.account);return new PublicSeat(s.name,s.bot,a!=null&&a.member(),a!=null&&a.annualMember(),a==null?"/api/avatars/system/0":a.avatarUrl(),a==null?"none":a.frame());}).toList(),r.game.equals("cards")?CardRules.visible(r.board,member(r,p)+1):r.game.equals("draw")?SketchRules.visible(r.board,member(r,p)+1):r.board,r.version,r.deadline,System.currentTimeMillis(),member(r,p));}
 private Room settle(Room r){if(!r.board.over())return r;for(int i=0;i<r.seats.size();i++){Seat s=r.seats.get(i);if(s.account==null)continue;int rank=r.game.equals("puzzle")?1:r.board.winner()==0?2:r.board.winner()==i+1?1:2;int points=rank==1?3:2;db.sql("insert into table_results(room_id,account_id,game,rank,points) values(:room,:account,:game,:rank,:points) on conflict do nothing").param("room",r.id).param("account",s.account).param("game",r.game).param("rank",rank).param("points",points).update();}return changed(r,"OVER",r.seats,r.board,0);}
 private Room tick(Room r){long now=System.currentTimeMillis();if(r.phase.equals("WAITING")&&r.deadline>0&&r.deadline<=now){var seats=new ArrayList<>(r.seats);seats.add(new Seat(null,null,"电脑",true));r=changed(r,"PLAYING",seats,r.board,now+30000);}
  if(r.phase.equals("PLAYING")&&r.game.equals("draw")){if(r.seats.get(r.board.turn()-1).bot&&r.board.history().isEmpty())r=changed(r,r.phase,r.seats,SketchRules.computer(r.board),r.deadline);if(r.deadline<=now){r=changed(r,"PLAYING",r.seats,SketchRules.advance(r.board,false),now+30000);r=settle(r);}return r;}if(r.phase.equals("PLAYING")&&((r.seats.get(r.board.turn()-1).bot&&(!r.game.equals("pool")||r.deadline-now<=28000))||r.deadline<=now)){var board=GridRules.move(r.board,r.board.turn(),GridRules.bot(r.board));r=changed(r,"PLAYING",r.seats,board,now+30000);r=settle(r);}return r;}
 private Room recover(Room r,UUID p){if(r.seats.stream().anyMatch(s->p.equals(s.principal)))return r;Seat fresh=seat(p);if(fresh.account==null)return r;for(int index=0;index<r.seats.size();index++){Seat old=r.seats.get(index);if(fresh.account.equals(old.account)){var seats=new ArrayList<>(r.seats);seats.set(index,new Seat(p,old.account,fresh.name,false));return changed(r,r.phase,seats,r.board,r.deadline);}}return r;}
 private Room bind(Room r,UUID p){if(r.board.over())return r;int index=member(r,p);Seat old=r.seats.get(index),fresh=seat(p);if((old.account==null&&fresh.account!=null)||old.bot){Seat replacement=old.account!=null?new Seat(p,old.account,old.name.replace("（托管）",""),false):fresh;if(replacement.account!=null&&r.seats.stream().anyMatch(s->replacement.account.equals(s.account)&&!p.equals(s.principal)))throw new ResponseStatusException(HttpStatus.CONFLICT,"same account already seated");var seats=new ArrayList<>(r.seats);seats.set(index,replacement);r=changed(r,r.phase,seats,r.board,r.deadline);}return r;}
 @Transactional public View create(String game,String mode,HttpServletRequest request){UUID p=principal(request);if(game==null||!Set.of("four","gomoku","puzzle","chess","draw","cards","pool").contains(game))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);if(mode==null||!Set.of("QUICK","FRIENDS").contains(mode))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  UUID joiningAccount=seat(p).account;
  // Serialize matchmaking across processes and duplicate create requests for an identity.
  db.sql("select pg_advisory_xact_lock(hashtext(:key))").param("key","table:"+game).query(Object.class).single();
  for(UUID id:db.sql("select id from table_rooms where game=:game and phase in ('WAITING','PLAYING') order by created_at desc").param("game",game).query(UUID.class).list()){Room r=read(id);if(r.seats.stream().anyMatch(s->(p.equals(s.principal)||joiningAccount!=null&&joiningAccount.equals(s.account))&&!s.bot)){r=recover(r,p);r=tick(bind(r,p));write(r);return view(r,p);}}
  if(mode.equals("QUICK"))for(UUID id:db.sql("select id from table_rooms where game=:game and phase='WAITING' order by created_at").param("game",game).query(UUID.class).list()){Room r=read(id);if(r.deadline==0)continue;if(r.deadline<=System.currentTimeMillis()){write(tick(r));continue;}var me=seat(p);if(me.account!=null&&r.seats.stream().anyMatch(s->me.account.equals(s.account)))continue;var seats=new ArrayList<>(r.seats);seats.add(me);r=changed(r,"PLAYING",seats,r.board,System.currentTimeMillis()+30000);write(r);return view(r,p);}
  Room r=new Room(UUID.randomUUID(),game,mode,"WAITING",List.of(seat(p)),GridRules.start(game),0,mode.equals("QUICK")?System.currentTimeMillis()+30000:0);db.sql("insert into table_rooms(id,game,origin,phase,state) values(:id,:game,:origin,:phase,:s)").param("id",r.id).param("game",game).param("origin",mode).param("phase",r.phase).param("s",json.writeValueAsString(r)).update();return view(r,p);}
 @Transactional public View join(UUID id,HttpServletRequest request){UUID p=principal(request);Room r=recover(read(id),p);if(r.seats.stream().anyMatch(s->p.equals(s.principal))){r=tick(bind(r,p));write(r);return view(r,p);}if(!r.phase.equals("WAITING")||r.seats.size()!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"room started");var me=seat(p);if(me.account!=null&&r.seats.stream().anyMatch(s->me.account.equals(s.account)))throw new ResponseStatusException(HttpStatus.CONFLICT,"same account");var seats=new ArrayList<>(r.seats);seats.add(me);r=changed(r,r.deadline>0?"PLAYING":"WAITING",seats,r.board,r.deadline>0?System.currentTimeMillis()+30000:0);write(r);return view(r,p);}
 @Transactional public View snapshot(UUID id,HttpServletRequest request){UUID p=principal(request);Room r=read(id);member(r,p);var next=db.sql("select successor_id from table_rooms where id=:id").param("id",id).query(UUID.class).optional();if(next.isPresent()){r=read(next.get());member(r,p);}r=tick(bind(r,p));write(r);return view(r,p);}
 @Transactional public View move(UUID id,UUID command,long version,int position,HttpServletRequest request){UUID p=principal(request);if(command==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);Room r=read(id);int you=member(r,p);if(db.sql("select count(*) from table_commands where room_id=:r and principal_id=:p and command_id=:c").param("r",id).param("p",p).param("c",command).query(Long.class).single()>0)return view(r,p);r=tick(bind(r,p));if(!r.phase.equals("PLAYING")||r.version!=version||r.board.turn()!=you+1){write(r);return view(r,p);}if(r.game.equals("draw"))throw new ResponseStatusException(HttpStatus.CONFLICT,"use sketch commands");try{r=changed(r,"PLAYING",r.seats,GridRules.move(r.board,you+1,position),System.currentTimeMillis()+30000);}catch(IllegalArgumentException|IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"illegal move");}db.sql("insert into table_commands values(:r,:p,:c)").param("r",id).param("p",p).param("c",command).update();r=settle(r);write(r);return view(r,p);}

 @Transactional public View sketch(UUID id,UUID command,long version,String action,String text,List<Integer> points,HttpServletRequest request){UUID p=principal(request);Room r=read(id);int you=member(r,p);if(command==null||!r.game.equals("draw"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);if(db.sql("select count(*) from table_commands where room_id=:r and principal_id=:p and command_id=:c").param("r",id).param("p",p).param("c",command).query(Long.class).single()>0)return view(r,p);r=tick(bind(r,p));if(!r.phase.equals("PLAYING")||r.version!=version){write(r);return view(r,p);}if("guess".equals(action)){String key=p+":"+r.board.moves();var guesses=new HashMap<String,Long>(r.guesses==null?Map.of():r.guesses);long now=System.currentTimeMillis();if(guesses.getOrDefault(key+":count",0L)>=6||now-guesses.getOrDefault(key+":time",0L)<1000)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"guess limit");guesses.put(key+":count",guesses.getOrDefault(key+":count",0L)+1);guesses.put(key+":time",now);r=new Room(r.id,r.game,r.origin,r.phase,r.seats,r.board,r.version,r.deadline,guesses);}try{var next=SketchRules.act(r.board,you+1,action,text,points);r=changed(r,r.phase,r.seats,next,next.moves()!=r.board.moves()?System.currentTimeMillis()+30000:r.deadline);}catch(IllegalArgumentException|IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"illegal drawing action");}db.sql("insert into table_commands values(:r,:p,:c)").param("r",id).param("p",p).param("c",command).update();r=settle(r);write(r);return view(r,p);}
 @Transactional public void leave(UUID id,HttpServletRequest request){UUID p=principal(request);Room r=read(id);int you=member(r,p);if(r.phase.equals("WAITING"))r=changed(r,"CLOSED",r.seats,r.board,0);else if(r.phase.equals("PLAYING")){var seats=new ArrayList<>(r.seats);Seat s=seats.get(you);seats.set(you,new Seat(s.principal,s.account,s.name+"（托管）",true));r=changed(r,r.phase,seats,r.board,System.currentTimeMillis());}write(r);}
 @Transactional public void advance(UUID id){Room r=read(id);Room next=tick(r);if(next!=r)write(next);}
 public List<UUID> pending(){return db.sql("select id from table_rooms where phase in ('WAITING','PLAYING')").query(UUID.class).list();}
 public record Statistics(long points,long completedGames) {}
 public Statistics statistics(String game,HttpServletRequest request){UUID p=principal(request);return db.sql("select coalesce(sum(t.points),0),count(t.room_id) from principals p left join table_results t on t.account_id=p.account_id and t.game=:game where p.id=:id").param("id",p).param("game",game).query((rs,n)->new Statistics(rs.getLong(1),rs.getLong(2))).single();}
 @Transactional public View rematch(UUID id,HttpServletRequest request){UUID p=principal(request);Room old=read(id);member(old,p);if(!old.phase.equals("OVER"))throw new ResponseStatusException(HttpStatus.CONFLICT);
  if(old.origin.equals("QUICK"))return create(old.game,"QUICK",request);
  var existing=db.sql("select successor_id from table_rooms where id=:id").param("id",id).query(UUID.class).optional();if(existing.isPresent())return view(read(existing.get()),p);
  db.sql("insert into table_rematch_votes values(:id,:p) on conflict do nothing").param("id",id).param("p",p).update();var votes=db.sql("select principal_id from table_rematch_votes where room_id=:id").param("id",id).query(UUID.class).list();
  if(old.seats.stream().filter(s->!s.bot).anyMatch(s->!votes.contains(s.principal)))return view(old,p);
  Room r=new Room(UUID.randomUUID(),old.game,"FRIENDS","PLAYING",old.seats,GridRules.start(old.game),0,System.currentTimeMillis()+30000);db.sql("insert into table_rooms(id,game,origin,phase,state) values(:id,:game,'FRIENDS','PLAYING',:state)").param("id",r.id).param("game",r.game).param("state",json.writeValueAsString(r)).update();db.sql("update table_rooms set successor_id=:next where id=:id").param("next",r.id).param("id",id).update();return view(r,p);}
 @Transactional public View ready(UUID id,HttpServletRequest request){UUID p=principal(request);Room r=read(id);member(r,p);if(!r.phase.equals("WAITING"))return view(r,p);db.sql("insert into table_room_ready values(:id,:p) on conflict do nothing").param("id",id).param("p",p).update();var votes=db.sql("select principal_id from table_room_ready where room_id=:id").param("id",id).query(UUID.class).list();if(r.seats.size()==2&&r.seats.stream().allMatch(seat->votes.contains(seat.principal)))r=changed(r,"PLAYING",r.seats,r.board,System.currentTimeMillis()+30000);else if(r.seats.size()==1&&r.deadline==0)r=changed(r,r.phase,r.seats,r.board,System.currentTimeMillis()+30000);write(r);return view(r,p);}

 public record Reaction(long id,int seat,String name,String emoji,long time) {}
 @Transactional public List<Reaction> reactions(UUID id,long after,HttpServletRequest request){UUID p=principal(request);Room room=read(id);member(room,p);return reactions(room,after);}
 private List<Reaction> reactions(Room room,long after){return db.sql("select id,principal_id,emoji,extract(epoch from created_at)*1000 as stamp from table_reactions where room_id=:room and id>:after and created_at>now()-interval '10 seconds' order by id limit 32").param("room",room.id).param("after",Math.max(0,after)).query((rs,n)->{UUID sender=rs.getObject("principal_id",UUID.class);int index=-1;for(int i=0;i<room.seats.size();i++)if(sender.equals(room.seats.get(i).principal)){index=i;break;}return new Reaction(rs.getLong("id"),index,index<0?"玩家":room.seats.get(index).name,rs.getString("emoji"),rs.getLong("stamp"));}).list();}
 @Transactional public List<Reaction> react(UUID id,UUID command,String emoji,HttpServletRequest request){UUID p=principal(request);Room room=read(id);member(room,p);if(command==null||!Set.of("😂","👋","🎉","😮","❤️","👍").contains(emoji==null?"":emoji))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);if(room.phase.equals("CLOSED"))throw new ResponseStatusException(HttpStatus.CONFLICT);boolean duplicate=db.sql("select count(*) from table_reactions where room_id=:room and principal_id=:p and command_id=:c").param("room",id).param("p",p).param("c",command).query(Long.class).single()>0;if(!duplicate){long recent=db.sql("select count(*) from table_reactions where room_id=:room and principal_id=:p and created_at>now()-interval '1500 milliseconds'").param("room",id).param("p",p).query(Long.class).single();if(recent>0)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);db.sql("insert into table_reactions(room_id,principal_id,command_id,emoji) values(:room,:p,:c,:emoji)").param("room",id).param("p",p).param("c",command).param("emoji",emoji).update();}return reactions(room,0);}
 public record Ranking(String name,long points,long games,boolean member,boolean annualMember,String avatarUrl,String frame) {}
 public List<Ranking> leaderboard(String game,String period){if(!Set.of("day","week","month").contains(period))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);return db.sql("select a.id,a.display_name,sum(t.points),count(*) from table_results t join accounts a on a.id=t.account_id where t.game=:game and t.created_at >= (date_trunc(:period,now() at time zone 'UTC') at time zone 'UTC') group by a.id,a.display_name order by sum(t.points) desc,count(*) desc,a.id limit 10").param("game",game).param("period",period).query((rs,n)->{var a=appearances.get(rs.getObject(1,UUID.class));return new Ranking(rs.getString(2),rs.getLong(3),rs.getLong(4),a.member(),a.annualMember(),a.avatarUrl(),a.frame());}).list();}
}